<?php declare(strict_types=1);$siteName=$content['site_name']??'VillaStay';$photo=static function(array $row):string{$v=(string)($row['cover_image']??'');return $v===''?'':(preg_match('~^https?://~i',$v)?$v:'/'.ltrim($v,'/'));}; ?><!doctype html><html lang="<?= e($locale??'tr') ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Destinasyonlar · <?= e($siteName) ?></title><?php $pageCssPath = \App\Core\ThemeManager::resolveFile('pages/destinations.css', 'default'); if ($pageCssPath !== null): ?><link rel="stylesheet" href="<?= e(\App\Core\ThemeManager::assetUrl('pages/destinations.css', 'default')) ?>?v=<?= (int)filemtime($pageCssPath) ?>"><?php endif; ?></head><body><main class="wrap"><div class="nav"><a href="/">← <?= e($siteName) ?></a><nav class="site-nav"><?php $navItems=$navigation??[];$navAllowAuth=true;\App\Core\ThemeManager::renderPartial('partials/navigation-items.php', get_defined_vars()); ?></nav></div><h1>Popüler tatil destinasyonları</h1><p>Türkiye'nin farklı bölgelerinde keşfedilecek tatil rotaları.</p><div class="grid"><?php foreach($destinations as $d): ?><a class="card" href="/konaklamalar?<?= e(http_build_query(['location_id'=>$d['location_id'],'city'=>$d['city']])) ?>"><?php if($photo($d)): ?><img src="<?= e($photo($d)) ?>" alt="<?= e($d['city']) ?>" loading="lazy"><?php endif; ?><strong><?= e($d['city']) ?> · <?= (int)$d['property_count'] ?> konaklama</strong></a><?php endforeach; ?></div></main><footer class="site-footer"><div class="footer-inner"><div class="footer-copy"><strong><?= e($siteName) ?></strong><p><?= e($content['footer_text']??'') ?></p></div><nav class="footer-links"><?php $navItems=$footerNavigation??[];$navAllowAuth=false;\App\Core\ThemeManager::renderPartial('partials/navigation-items.php', get_defined_vars()); ?></nav></div></footer><?php \App\Core\ThemeManager::renderPartial('partials/login-modal.php', get_defined_vars()); ?></body></html>